window.PMP_WORDS = (window.PMP_WORDS || []).concat([
{"id":0,"en":"Project","say":"Project","also":[],"gloss":"项目","explain":"为创造独特的产品、服务或成果而做的临时性工作，有明确的开始和结束。","band":"前面","ipa":"ˈprɑʤɛkt"},
{"id":1,"en":"Project Management","say":"Project Management","also":[],"gloss":"项目管理","explain":"把知识、技能、工具和技术用到项目活动上，使项目满足要求。","band":"前面","ipa":"ˈprɑʤɛkt ˈmænɪʤmənt"},
{"id":2,"en":"Project Manager (PM)","say":"Project Manager","also":["pm"],"gloss":"项目经理","explain":"被组织委派去领导项目团队、对项目目标负责的人。","band":"前面","ipa":"ˈprɑʤɛkt ˈmænɪʤər"},
{"id":3,"en":"Stakeholder","say":"Stakeholder","also":[],"gloss":"干系人","explain":"会受项目影响，或能影响项目的人、群体和组织。第6版译作相关方。","band":"前面","ipa":"ˈsteɪˌkhoʊldər"},
{"id":4,"en":"Sponsor","say":"Sponsor","also":[],"gloss":"发起人","explain":"为项目提供资源、拍板支持，并在方向不清时帮项目推进的人。","band":"前面","ipa":"ˈspɑnsər"},
{"id":5,"en":"Customer","say":"Customer","also":[],"gloss":"客户","explain":"最终接收或使用项目成果的一方，验收通常要过他们这一关。","band":"前面","ipa":"ˈkəstəmər"},
{"id":6,"en":"End User","say":"End User","also":[],"gloss":"最终用户","explain":"真正每天使用产品的人，和出钱的客户不一定是同一人。","band":"前面","ipa":"ɛnd ˈjuzər"},
{"id":7,"en":"Project Team","say":"Project Team","also":[],"gloss":"项目团队","explain":"一起做项目工作的人，包括项目经理和执行具体任务的成员。","band":"前面","ipa":"ˈprɑʤɛkt tim"},
{"id":8,"en":"Team Member","say":"Team Member","also":[],"gloss":"团队成员","explain":"在项目里承担具体工作的人，不一定拥有项目决策权。","band":"前面","ipa":"tim ˈmɛmbər"},
{"id":9,"en":"Subject Matter Expert (SME)","say":"Subject Matter Expert","also":["sme"],"gloss":"主题专家","explain":"某一专业领域里能把关内容和做法的专家。","band":"前面","ipa":"ˈsəbʤɪkt ˈmætər ˈɛkspərt"},
{"id":10,"en":"Deliverable","say":"Deliverable","also":[],"gloss":"可交付成果","explain":"项目必须交出来的、可验证的产品、服务或成果。","band":"前面","ipa":"dɪˈlɪvərəbəl"},
{"id":11,"en":"Milestone","say":"Milestone","also":[],"gloss":"里程碑","explain":"进度上的重要时点，工期通常为零，用来标记阶段完成。","band":"前面","ipa":"ˈmaɪlˌstoʊn"},
{"id":12,"en":"Requirement","say":"Requirement","also":[],"gloss":"需求","explain":"干系人想要的条件或能力，满足了才能说成果合格。","band":"前面","ipa":"rɪkˈwaɪrmənt"},
{"id":13,"en":"Scope","say":"Scope","also":[],"gloss":"范围","explain":"项目要做、以及明确不做的工作边界。","band":"前面","ipa":"skoʊp"},
{"id":923,"en":"Producer","say":"Producer","also":[],"gloss":"制作人","explain":"游戏项目里负责范围、进度、预算和跨职能协同的人，对外常对接发行方。","band":"前面","ipa":"prəˈdusər","tag":"游戏"},
{"id":14,"en":"Schedule","say":"Schedule","also":[],"gloss":"进度","explain":"活动何时开始、何时结束，以及它们如何串起来的时间安排。","band":"前面","ipa":"ˈskɛʤʊl"},
{"id":15,"en":"Cost","say":"Cost","also":[],"gloss":"成本","explain":"完成项目工作要花的钱，包括人力、材料和采购。","band":"前面","ipa":"kɔst"},
{"id":16,"en":"Quality","say":"Quality","also":[],"gloss":"质量","explain":"一套固有特性满足要求的程度。做得符合要求，就是质量高。","band":"前面","ipa":"kˈwɑləti"},
{"id":17,"en":"Grade","say":"Grade","also":[],"gloss":"等级","explain":"功能或技术档次的类别。低档次也可以是高质量，只要符合该档次的要求。","band":"前面","ipa":"greɪd"},
{"id":18,"en":"Resource","say":"Resource","also":[],"gloss":"资源","explain":"完成工作所需的人、设备、材料和资金。","band":"前面","ipa":"ˈrisɔrs"},
{"id":19,"en":"Risk","say":"Risk","also":[],"gloss":"风险","explain":"一旦发生，会对目标产生正面或负面影响的不确定事件。还没发生。","band":"前面","ipa":"rɪsk"},
{"id":20,"en":"Issue","say":"Issue","also":[],"gloss":"问题","explain":"已经发生、需要处理的事项。它不是风险，因为事情已经落地了。","band":"前面","ipa":"ˈɪʃu"},
{"id":21,"en":"Change","say":"Change","also":[],"gloss":"变更","explain":"相对已批准计划的修改。要走变更控制，不能私下加进去。","band":"前面","ipa":"ʧeɪnʤ"},
{"id":22,"en":"Baseline","say":"Baseline","also":[],"gloss":"基准","explain":"经批准的范围、进度或成本计划。以后的偏差都拿它做对照。","band":"前面","ipa":"ˈbeɪsˌlaɪn"},
{"id":23,"en":"Objective","say":"Objective","also":[],"gloss":"目标","explain":"项目要达到的结果，包含成果、产出和效益，最好能衡量。","band":"前面","ipa":"əˈbʤɛktɪv"},
{"id":24,"en":"Success Criteria","say":"Success Criteria","also":[],"gloss":"成功标准","explain":"事先约定的、用来判断项目是否成功的标准。","band":"前面","ipa":"səkˈsɛs kraɪˈtɪriə"},
{"id":25,"en":"Acceptance Criteria","say":"Acceptance Criteria","also":[],"gloss":"验收标准","explain":"可交付成果必须满足的条件，验收时就看这些。","band":"前面","ipa":"əkˈsɛptəns kraɪˈtɪriə"},
{"id":26,"en":"Assumption","say":"Assumption","also":[],"gloss":"假设","explain":"规划时当作真的、但未经证实的因素。假设一破，常常变成风险。","band":"前面","ipa":"əˈsəmpʃən"},
{"id":27,"en":"Constraint","say":"Constraint","also":[],"gloss":"制约因素","explain":"限制项目选择的因素，比如固定的截止日期、预算或法规。","band":"前面","ipa":"kənˈstreɪnt"},
{"id":924,"en":"Publisher","say":"Publisher","also":[],"gloss":"发行商","explain":"出资、发行，并按里程碑验收版本的一方。开发团队要按约定交可玩包。","band":"前面","ipa":"ˈpəblɪʃər","tag":"游戏"},
{"id":28,"en":"Dependency","say":"Dependency","also":[],"gloss":"依赖关系","explain":"一项工作必须等另一项，或必须和另一项同步，这种关系就是依赖。","band":"前面","ipa":"dɪˈpɛndənsi"},
{"id":29,"en":"Product","say":"Product","also":[],"gloss":"产品","explain":"项目造出来、可以交给别人使用的有形或无形物品。","band":"前面","ipa":"ˈprɑdəkt"},
{"id":30,"en":"Service","say":"Service","also":[],"gloss":"服务","explain":"项目提供的能力或劳务，本身就是交付物。","band":"前面","ipa":"ˈsərvɪs"},
{"id":31,"en":"Result","say":"Result","also":[],"gloss":"成果","explain":"项目带来的结果，可能是一种状态或能力，而不只是一件物品。","band":"前面","ipa":"rɪˈzəlt"},
{"id":32,"en":"Output","say":"Output","also":[],"gloss":"输出","explain":"做出来的交付物本身，比如一份报告或一个功能。","band":"前面","ipa":"ˈaʊtˌpʊt"},
{"id":33,"en":"Outcome","say":"Outcome","also":[],"gloss":"成果","explain":"交付物投入使用之后带来的结果，比输出更靠近价值。","band":"前面","ipa":"ˈaʊtˌkəm"},
{"id":34,"en":"Benefit","say":"Benefit","also":[],"gloss":"效益","explain":"成果给组织带来的收益，项目结束后还要继续看它有没有实现。","band":"前面","ipa":"ˈbɛnəfɪt"},
{"id":35,"en":"Value","say":"Value","also":[],"gloss":"价值","explain":"成果值得组织投入的原因，包括财务收益和非财务收益。","band":"前面","ipa":"ˈvælju"},
{"id":36,"en":"Business Value","say":"Business Value","also":[],"gloss":"商业价值","explain":"项目对组织业务有多少好处，是选择和继续项目的依据。","band":"前面","ipa":"ˈbɪznɪs ˈvælju"},
{"id":37,"en":"Phase","say":"Phase","also":[],"gloss":"阶段","explain":"项目生命周期中的一段，结束时通常有一次继续或停止的检查。","band":"前面","ipa":"feɪz"},
{"id":38,"en":"Project Life Cycle","say":"Project Life Cycle","also":[],"gloss":"项目生命周期","explain":"项目从启动到收尾所经历的一系列阶段。","band":"前面","ipa":"ˈprɑʤɛkt laɪf ˈsaɪkəl"},
{"id":39,"en":"Product Life Cycle","say":"Product Life Cycle","also":[],"gloss":"产品生命周期","explain":"产品从概念、成长、成熟到退出的全过程，通常比单个项目更长。","band":"前面","ipa":"ˈprɑdəkt laɪf ˈsaɪkəl"},
{"id":40,"en":"Kick-off Meeting","say":"Kick-off Meeting","also":[],"gloss":"开工会议","explain":"计划大致就绪后召开，让团队和干系人对齐目标、角色和规则。","band":"前面","ipa":"kɪk ɔf ˈmitɪŋ"},
{"id":41,"en":"Status Meeting","say":"Status Meeting","also":[],"gloss":"状态会议","explain":"定期看进展、偏差和问题，决定下一步怎么调整。","band":"前面","ipa":"ˈstætəs ˈmitɪŋ"},
{"id":925,"en":"Developer","say":"Developer","also":[],"gloss":"开发商","explain":"实际制作游戏的团队或公司。它和发行商可以是同一家，也可以分开。","band":"前面","ipa":"dɪˈvɛləpər","tag":"游戏"},
{"id":42,"en":"Progress","say":"Progress","also":[],"gloss":"进展","explain":"工作已经完成到什么程度，通常对照计划来讲。","band":"前面","ipa":"ˈprɑˌgrɛs"},
{"id":43,"en":"Performance","say":"Performance","also":[],"gloss":"绩效","explain":"实际做得怎么样，常用范围、进度、成本来衡量。","band":"前面","ipa":"pərˈfɔrməns"},
{"id":44,"en":"Variance","say":"Variance","also":[],"gloss":"偏差","explain":"实际和基准之间的差。进度偏差、成本偏差都是这一类。","band":"前面","ipa":"ˈvɛriəns"},
{"id":45,"en":"Forecast","say":"Forecast","also":[],"gloss":"预测","explain":"根据已经发生的绩效，估计剩下的工作和结尾会怎样。","band":"前面","ipa":"ˈfɔrˌkæst"},
{"id":46,"en":"Budget","say":"Budget","also":[],"gloss":"预算","explain":"经批准、用来完成项目的全部资金，包含成本基准和管理储备。","band":"前面","ipa":"ˈbəʤɪt"},
{"id":47,"en":"Estimate","say":"Estimate","also":[],"gloss":"估算","explain":"对工期、成本或资源给出的近似值，会随着信息变多而变准。","band":"前面","ipa":"ˈɛstəˌmeɪt"},
{"id":48,"en":"Priority","say":"Priority","also":[],"gloss":"优先级","explain":"事情该先做哪件。资源不够时，靠优先级取舍。","band":"前面","ipa":"praɪˈɔrəti"},
{"id":49,"en":"Decision","say":"Decision","also":[],"gloss":"决策","explain":"在若干方案里做出选择，并让团队按这个选择执行。","band":"前面","ipa":"dɪˈsɪʒən"},
{"id":50,"en":"Approval","say":"Approval","also":[],"gloss":"批准","explain":"有权的人对计划、成果或变更表示正式同意。","band":"前面","ipa":"əˈpruvəl"},
{"id":51,"en":"Sign-off","say":"Sign-off","also":[],"gloss":"签字验收","explain":"用签字或等效方式确认验收或批准，留下正式记录。","band":"前面","ipa":"saɪn ɔf"},
{"id":52,"en":"Handover","say":"Handover","also":[],"gloss":"移交","explain":"把最终产品、服务或成果交给运营或客户，项目由此收口。","band":"前面","ipa":"ˈhændoʊvər"},
{"id":53,"en":"Closure","say":"Closure","also":[],"gloss":"收尾","explain":"项目或阶段的结尾：验收、移交、释放资源、归档经验。","band":"前面","ipa":"ˈkloʊʒər"},
{"id":54,"en":"Lessons Learned","say":"Lessons Learned","also":[],"gloss":"经验教训","explain":"项目里什么有效、什么该改。要写下来，供以后的项目用。","band":"前面","ipa":"ˈlɛsənz ˈlərnɪd"},
{"id":55,"en":"Action Item","say":"Action Item","also":[],"gloss":"行动项","explain":"会上或问题里定下来、有人负责去办的具体事项。","band":"前面","ipa":"ˈækʃən ˈaɪtəm"},
{"id":926,"en":"Build","say":"Build","also":[],"gloss":"构建版本","explain":"一次能安装、能运行的游戏包，用来评审、试玩或提交平台。","band":"前面","ipa":"bɪld","tag":"游戏"},
{"id":56,"en":"Owner","say":"Owner","also":[],"gloss":"责任人","explain":"对某件事负责跟进的人，比如风险责任人或行动项负责人。","band":"前面","ipa":"ˈoʊnər"},
{"id":57,"en":"Role","say":"Role","also":[],"gloss":"角色","explain":"一个人在项目里扮演的位置，决定他参与哪些事。","band":"前面","ipa":"roʊl"},
{"id":58,"en":"Responsibility","say":"Responsibility","also":[],"gloss":"职责","explain":"这个角色具体要做的工作。RACI 里的执行，偏“动手做”。","band":"前面","ipa":"riˌspɑnsəˈbɪləti"},
{"id":59,"en":"Accountability","say":"Accountability","also":[],"gloss":"问责","explain":"最终被问责的那一位。一件事只能有一个问责人。","band":"前面","ipa":"əˈkaʊntəˌbɪlɪti"},
{"id":60,"en":"Authority","say":"Authority","also":[],"gloss":"职权","explain":"可以做决定、动用资源和签字的权力。职权不够，很多变更推不动。","band":"前面","ipa":"əˈθɔrəti"},
{"id":61,"en":"Communication","say":"Communication","also":[],"gloss":"沟通","explain":"信息的产生、传递和理解。项目失败常常出在这里。","band":"前面","ipa":"kəmˌjunəˈkeɪʃən"},
{"id":62,"en":"Report","say":"Report","also":[],"gloss":"报告","explain":"把绩效、风险或状态整理给干系人看的文件。","band":"前面","ipa":"rɪˈpɔrt"},
{"id":63,"en":"Documentation","say":"Documentation","also":[],"gloss":"文档","explain":"项目过程中留下的书面记录，方便追溯和交接。","band":"前面","ipa":"ˌdɑkjəmɛnˈteɪʃən"},
{"id":64,"en":"Template","say":"Template","also":[],"gloss":"模板","explain":"组织里现成的格式。新项目可以直接套，少做无用功。","band":"前面","ipa":"ˈtɛmplət"},
{"id":65,"en":"Policy","say":"Policy","also":[],"gloss":"政策","explain":"组织规定必须遵守的原则，项目通常改不了它。","band":"前面","ipa":"ˈpɑləsi"},
{"id":66,"en":"Procedure","say":"Procedure","also":[],"gloss":"程序","explain":"把政策落实成一步步怎么做的操作说明。","band":"前面","ipa":"prəˈsiʤər"},
{"id":67,"en":"Guideline","say":"Guideline","also":[],"gloss":"指南","explain":"建议性的做法，比政策和程序更灵活。","band":"前面","ipa":"ˈgaɪˌdlaɪn"},
{"id":68,"en":"Standard","say":"Standard","also":[],"gloss":"标准","explain":"公认或组织规定的规范，质量要求经常引用它。","band":"前面","ipa":"ˈstændərd"},
{"id":69,"en":"Regulation","say":"Regulation","also":[],"gloss":"法规","explain":"政府或监管机构的强制规定，不合规就不能交付。","band":"前面","ipa":"ˌrɛgjəˈleɪʃən"},
{"id":927,"en":"Playtest","say":"Playtest","also":[],"gloss":"试玩","explain":"让内部人员或玩家真正玩一遍，用来发现流程、手感和难懂的地方。","band":"前面","ipa":"ˈpleɪˌtɛst","tag":"游戏"},
{"id":70,"en":"Compliance","say":"Compliance","also":[],"gloss":"合规","explain":"工作是否符合法规、标准和合同。听这个词时想“有没有违规”。","band":"前面","ipa":"kəmˈplaɪəns"},
{"id":71,"en":"Governance","say":"Governance","also":[],"gloss":"治理","explain":"谁有权做决定、如何监督项目与组织目标一致的框架。","band":"前面","ipa":"ˈgəvərnəns"},
{"id":72,"en":"Strategy","say":"Strategy","also":[],"gloss":"战略","explain":"组织长期要赢的方向。项目应当为战略服务。","band":"前面","ipa":"ˈstrætəʤi"},
{"id":73,"en":"Vision","say":"Vision","also":[],"gloss":"愿景","explain":"组织或产品想成为什么样，是方向，不是本周任务。","band":"前面","ipa":"ˈvɪʒən"},
{"id":74,"en":"Mission","say":"Mission","also":[],"gloss":"使命","explain":"组织存在的目的，说明它为谁创造什么。","band":"前面","ipa":"ˈmɪʃən"},
{"id":75,"en":"Key Performance Indicator (KPI)","say":"Key Performance Indicator","also":["kpi"],"gloss":"关键绩效指标","explain":"用来判断目标有没有达成的少数关键数字。","band":"前面","ipa":"ki pərˈfɔrməns ˈɪndəˌkeɪtər"},
{"id":76,"en":"Metric","say":"Metric","also":[],"gloss":"测量指标","explain":"可以测量的指标。没有测量指标，偏差就只是感觉。","band":"前面","ipa":"ˈmɛtrɪk"},
{"id":77,"en":"Threshold","say":"Threshold","also":[],"gloss":"临界值","explain":"越过这条线就要采取行动，比如成本偏差超过 10% 必须上报。","band":"前面","ipa":"θˈrɛˌʃoʊld"},
{"id":78,"en":"Tolerance","say":"Tolerance","also":[],"gloss":"公差","explain":"还能接受的偏差范围。停在公差内通常不必升级处理。","band":"前面","ipa":"ˈtɑlərəns"},
{"id":79,"en":"Escalation","say":"Escalation","also":[],"gloss":"上报","explain":"事情超出项目经理权限时，交给上一层去决定。","band":"前面","ipa":"ˌɛskəˈleɪʃən"},
{"id":80,"en":"Task","say":"Task","also":[],"gloss":"任务","explain":"比活动更细的一件具体工作，看板上的一张卡片常常就是任务。","band":"前面","ipa":"tæsk"},
{"id":81,"en":"Activity","say":"Activity","also":[],"gloss":"活动","explain":"进度里要估算工期、排出顺序的工作单元，由工作包分解而来。","band":"前面","ipa":"ækˈtɪvɪti"},
{"id":82,"en":"Effort","say":"Effort","also":[],"gloss":"人力投入","explain":"要投入多少人工，比如人天。它不等于日历上的持续时间。","band":"前面","ipa":"ˈɛfərt"},
{"id":83,"en":"Duration","say":"Duration","also":[],"gloss":"持续时间","explain":"从开始到结束的工作时段，受日历和资源影响，不只是人力投入。","band":"前面","ipa":"ˈdʊˈreɪʃən"},
{"id":928,"en":"Blocker","say":"Blocker","also":[],"gloss":"阻断缺陷","explain":"不修就无法继续测试、验收或出货的缺陷。分诊时排在最前。","band":"前面","ipa":"ˈblɑkər","tag":"游戏"},
{"id":84,"en":"Deadline","say":"Deadline","also":[],"gloss":"完成期限","explain":"必须完成的日期。它常常是制约因素，而不是估算出来的工期。","band":"前面","ipa":"ˈdɛˌdlaɪn"},
{"id":85,"en":"Resource Calendar","say":"Resource Calendar","also":[],"gloss":"资源日历","explain":"某个资源哪天能上班、一天能投入多少的日历。","band":"前面","ipa":"ˈrisɔrs ˈkæləndər"},
{"id":86,"en":"Project Calendar","say":"Project Calendar","also":[],"gloss":"项目日历","explain":"项目整体哪天工作、哪天停工的日历，排进度时要用它。","band":"前面","ipa":"ˈprɑʤɛkt ˈkæləndər"},
{"id":280,"en":"Agile","say":"Agile","also":[],"gloss":"敏捷","explain":"用短周期、频繁反馈和持续交付来应对变化的一套方法。","band":"敏捷","ipa":"ˈæʤəl"},
{"id":281,"en":"Hybrid Approach","say":"Hybrid Approach","also":[],"gloss":"混合方法","explain":"在同一个项目里混用预测型和敏捷做法。","band":"敏捷","ipa":"ˈhaɪbrɪd əˈproʊʧ"},
{"id":282,"en":"Scrum","say":"Scrum","also":[],"gloss":"Scrum","explain":"一种敏捷框架，用固定长度的冲刺交付增量，角色和事件是规定好的。","band":"敏捷","ipa":"scrum"},
{"id":283,"en":"Kanban","say":"Kanban","also":[],"gloss":"看板","explain":"把工作可视化，并限制同时进行的数量，让流动顺畅。","band":"敏捷","ipa":"kanban"},
{"id":284,"en":"Lean","say":"Lean","also":[],"gloss":"精益","explain":"以减少浪费、让价值顺畅流动为核心的方法。","band":"敏捷","ipa":"lin"},
{"id":285,"en":"Product Owner","say":"Product Owner","also":[],"gloss":"产品负责人","explain":"对产品价值负责的人，排定待办顺序，并接受增量。","band":"敏捷","ipa":"ˈprɑdəkt ˈoʊnər"},
{"id":286,"en":"Scrum Master","say":"Scrum Master","also":[],"gloss":"Scrum Master","explain":"帮助团队守住 Scrum、排除障碍的服务型角色，不是传统意义上发号施令的经理。","band":"敏捷","ipa":"scrum ˈmæstər"},
{"id":929,"en":"Vertical Slice","say":"Vertical Slice","also":[],"gloss":"垂直切片","explain":"把一个小功能从玩法、程序、美术做到能玩，用来在全面铺开前验证方向。","band":"敏捷","ipa":"ˈvərtɪkəl slaɪs","tag":"游戏"},
{"id":287,"en":"Development Team","say":"Development Team","also":[],"gloss":"开发团队","explain":"和项目团队的建设、管理或工作方式有关。","band":"敏捷","ipa":"dɪˈvɛləpmənt tim"},
{"id":288,"en":"Cross-functional Team","say":"Cross-functional Team","also":[],"gloss":"跨职能团队","explain":"和项目团队的建设、管理或工作方式有关。","band":"敏捷","ipa":"krɔs ˈfəŋkʃənəl tim"},
{"id":289,"en":"Self-organizing Team","say":"Self-organizing Team","also":[],"gloss":"自组织团队","explain":"和项目团队的建设、管理或工作方式有关。","band":"敏捷","ipa":"ˌsɛlˌfɔrgənɪzɪŋ tim"},
{"id":290,"en":"Servant Leadership","say":"Servant Leadership","also":[],"gloss":"服务型领导","explain":"领导者先帮助团队排除障碍、成长和做决定，而不是靠命令推动。","band":"敏捷","ipa":"ˈsərvənt ˈlidərˌʃɪp"},
{"id":291,"en":"Sprint","say":"Sprint","also":[],"gloss":"冲刺","explain":"Scrum 里固定长度的短周期，结束时要交出可用增量。","band":"敏捷","ipa":"sprɪnt"},
{"id":292,"en":"Iteration","say":"Iteration","also":[],"gloss":"迭代","explain":"一段固定时间内完成一小轮计划、做和评审的循环。","band":"敏捷","ipa":"ˌɪtəˈreɪʃən"},
{"id":293,"en":"Timebox","say":"Timebox","also":[],"gloss":"时间盒","explain":"给一段工作规定固定时长，时间到了就停下来检查。","band":"敏捷","ipa":"timebox"},
{"id":930,"en":"Greybox","say":"Greybox","also":[],"gloss":"灰盒","explain":"用简单几何块先把关卡和玩法跑通，不在这一步追求最终美术。","band":"敏捷","ipa":"ˈgreɪˌbɑks","tag":"游戏"},
{"id":294,"en":"Product Backlog","say":"Product Backlog","also":[],"gloss":"产品待办事项列表","explain":"产品还没做的需求清单，顺序由产品负责人维护。","band":"敏捷","ipa":"ˈprɑdəkt ˈbæˌklɔg"},
{"id":295,"en":"Sprint Backlog","say":"Sprint Backlog","also":[],"gloss":"冲刺待办事项列表","explain":"这个冲刺选定的事项，加上交付它们的计划。","band":"敏捷","ipa":"sprɪnt ˈbæˌklɔg"},
{"id":296,"en":"Backlog Refinement","say":"Backlog Refinement","also":[],"gloss":"待办事项细化","explain":"把待办事项拆细、补充细节并重新排序，旧称梳理。","band":"敏捷","ipa":"ˈbæˌklɔg rəˈfaɪnmənt"},
{"id":297,"en":"User Story","say":"User Story","also":[],"gloss":"用户故事","explain":"从用户角度写的一小段需求，通常配有验收标准。","band":"敏捷","ipa":"ˈjuzər ˈstɔri"},
{"id":298,"en":"Epic","say":"Epic","also":[],"gloss":"史诗","explain":"很大的用户故事，还要再拆成更小的故事才能做。","band":"敏捷","ipa":"ˈɛpɪk"},
{"id":299,"en":"Theme","say":"Theme","also":[],"gloss":"主题","explain":"把一组相关故事归到同一个业务主题下。","band":"敏捷","ipa":"θim"},
{"id":300,"en":"Feature","say":"Feature","also":[],"gloss":"特性","explain":"用户能感知的一项功能，通常由若干故事组成。","band":"敏捷","ipa":"ˈfiʧər"},
{"id":931,"en":"First Playable","say":"First Playable","also":[],"gloss":"首次可玩","explain":"核心循环第一次能完整玩下来的版本，用来判断好不好玩。","band":"敏捷","ipa":"fərst ˈpleɪəbəl","tag":"游戏"},
{"id":301,"en":"Story Point","say":"Story Point","also":[],"gloss":"故事点","explain":"相对估算用的点数，表示工作量和复杂度，不是小时。","band":"敏捷","ipa":"ˈstɔri pɔɪnt"},
{"id":302,"en":"Relative Estimating","say":"Relative Estimating","also":[],"gloss":"相对估算","explain":"一种估算路子。先听它靠的是历史类比、公式，还是从底层往上加。","band":"敏捷","ipa":"ˈrɛlətɪv ˈɛstəˌmeɪtɪŋ"},
{"id":303,"en":"Planning Poker","say":"Planning Poker","also":[],"gloss":"计划扑克牌","explain":"团队出牌估算故事点，差异大就讨论，直到意见靠近。","band":"敏捷","ipa":"ˈplænɪŋ ˈpoʊkər"},
{"id":304,"en":"Velocity","say":"Velocity","also":[],"gloss":"速度","explain":"团队在一个迭代里实际完成的工作量，用来预测以后能做多少。","band":"敏捷","ipa":"vəˈlɑsəti"},
{"id":305,"en":"Burndown Chart","say":"Burndown Chart","also":[],"gloss":"燃尽图","explain":"显示剩余工作随时间下降的图。线不下降，就是没在消耗工作。","band":"敏捷","ipa":"burndown ʧɑrt"},
{"id":306,"en":"Burnup Chart","say":"Burnup Chart","also":[],"gloss":"燃起图","explain":"显示已完成工作上升的图，范围变化时比燃尽图更不容易误读。","band":"敏捷","ipa":"ˈbərˌnəp ʧɑrt"},
{"id":307,"en":"Task Board","say":"Task Board","also":[],"gloss":"任务板","explain":"用栏目显示待办、进行中和完成，让工作状态一眼可见。","band":"敏捷","ipa":"tæsk bɔrd"},
{"id":932,"en":"Feature Freeze","say":"Feature Freeze","also":[],"gloss":"功能冻结","explain":"到这个时点不再加新功能，只修缺陷、调手感和打磨。","band":"敏捷","ipa":"ˈfiʧər friz","tag":"游戏"},
{"id":308,"en":"Daily Standup","say":"Daily Standup","also":[],"gloss":"每日站会","explain":"很短的每日同步，看昨天、今天和障碍，不是状态汇报大会。","band":"敏捷","ipa":"ˈdeɪli ˈstænˌdəp"},
{"id":309,"en":"Sprint Planning","say":"Sprint Planning","also":[],"gloss":"冲刺规划","explain":"冲刺开始时选定本轮要做的事项，并定出冲刺目标。","band":"敏捷","ipa":"sprɪnt ˈplænɪŋ"},
{"id":310,"en":"Sprint Review","say":"Sprint Review","also":[],"gloss":"冲刺评审","explain":"向干系人演示增量，收集反馈，决定下一步做什么。","band":"敏捷","ipa":"sprɪnt ˌrivˈju"},
{"id":311,"en":"Sprint Retrospective","say":"Sprint Retrospective","also":[],"gloss":"冲刺回顾","explain":"冲刺结束后团队反省协作和过程，决定下个冲刺改进什么。","band":"敏捷","ipa":"sprɪnt ˌrɛtrəˈspɛktɪv"},
{"id":312,"en":"Retrospective","say":"Retrospective","also":[],"gloss":"回顾会议","explain":"团队回头看过程本身，决定下轮怎么改进协作。","band":"敏捷","ipa":"ˌrɛtrəˈspɛktɪv"},
{"id":313,"en":"Increment","say":"Increment","also":[],"gloss":"增量","explain":"这一轮做完、符合完成定义、可以拿去用的成果。","band":"敏捷","ipa":"ˈɪnkrəmənt"},
{"id":314,"en":"Potentially Shippable Increment","say":"Potentially Shippable Increment","also":[],"gloss":"潜在可交付增量","explain":"达到完成定义、随时可以交付的增量。","band":"敏捷","ipa":"pəˈtɛnʃəli shippable ˈɪnkrəmənt"},
{"id":933,"en":"Bug Triage","say":"Bug Triage","also":[],"gloss":"缺陷分诊","explain":"定期把缺陷按严重程度、是否挡住出货来排序，决定先修哪一个。","band":"敏捷","ipa":"bəg ˈtriɑʒ","tag":"游戏"},
{"id":315,"en":"Definition of Done (DoD)","say":"Definition of Done","also":["dod"],"gloss":"完成的定义","explain":"团队一致同意的“怎样才算做完”。没达到，就不能当完成。","band":"敏捷","ipa":"ˌdɛfəˈnɪʃən əv dən"},
{"id":316,"en":"Definition of Ready (DoR)","say":"Definition of Ready","also":["dor"],"gloss":"就绪的定义","explain":"故事进入迭代之前要满足的条件，比如验收标准已经写清。","band":"敏捷","ipa":"ˌdɛfəˈnɪʃən əv ˈrɛdi"},
{"id":317,"en":"Minimum Viable Product (MVP)","say":"Minimum Viable Product","also":["mvp"],"gloss":"最小可行产品","explain":"用最少功能验证这个想法值不值得继续做的版本。","band":"敏捷","ipa":"ˈmɪnəməm ˈvaɪəbəl ˈprɑdəkt"},
{"id":318,"en":"Product Vision","say":"Product Vision","also":[],"gloss":"产品愿景","explain":"产品要为谁解决什么问题的长期方向。","band":"敏捷","ipa":"ˈprɑdəkt ˈvɪʒən"},
{"id":319,"en":"Product Roadmap","say":"Product Roadmap","also":[],"gloss":"产品路线图","explain":"产品大致按什么顺序、在什么时间段交付价值的路线。","band":"敏捷","ipa":"ˈprɑdəkt roadmap"},
{"id":331,"en":"Impediment","say":"Impediment","also":[],"gloss":"障碍因素","explain":"挡住团队前进的障碍，每日站会要把它暴露出来。","band":"敏捷","ipa":"ˌɪmˈpɛdəmənt"},
{"id":332,"en":"Technical Debt","say":"Technical Debt","also":[],"gloss":"技术债","explain":"为了赶进度留下的粗糙实现，以后要还，否则会拖慢后续开发。","band":"敏捷","ipa":"ˈtɛknɪkəl dɛt"},
{"id":934,"en":"Showstopper","say":"Showstopper","also":[],"gloss":"出货阻断","explain":"不解决就不能发售或提交平台的问题，比一般缺陷更优先。","band":"敏捷","ipa":"ˈʃoʊˌstɑpər","tag":"游戏"},
{"id":333,"en":"Spike","say":"Spike","also":[],"gloss":"探针","explain":"为了弄清未知而做的短时探索，本身通常不直接交付功能。","band":"敏捷","ipa":"spaɪk"},
{"id":334,"en":"Empirical Process","say":"Empirical Process","also":[],"gloss":"经验过程","explain":"靠透明、检视和调整来控制过程，而不是靠事先把一切计划死。","band":"敏捷","ipa":"ˌɛmˈpɪrɪkəl ˈprɔˌsɛs"},
{"id":335,"en":"Transparency","say":"Transparency","also":[],"gloss":"透明","explain":"过程和成果对相关的人可见，大家看到的是同一份事实。","band":"敏捷","ipa":"trænˈspɛrənsi"},
{"id":336,"en":"Inspection","say":"Inspection","also":[],"gloss":"检查","explain":"对照要求检查成果。质量控制里的检查产出核实的可交付成果；敏捷里的检视则是经验主义的支柱。","band":"敏捷","ipa":"ˌɪnˈspɛkʃən"},
{"id":337,"en":"Adaptation","say":"Adaptation","also":[],"gloss":"适应","explain":"检视之后立刻调整计划或做法。","band":"敏捷","ipa":"ˌædəpˈteɪʃən"},
{"id":338,"en":"Scrum Values","say":"Scrum Values","also":[],"gloss":"Scrum 价值观：承诺、专注、开放、尊重、勇气","explain":"承诺、专注、开放、尊重、勇气。Scrum 靠这些价值观才能跑起来。","band":"敏捷","ipa":"scrum ˈvæljuz"},
{"id":339,"en":"Sustainable Pace","say":"Sustainable Pace","also":[],"gloss":"可持续节奏","explain":"团队能长期保持的工作节奏，不靠持续加班。","band":"敏捷","ipa":"səˈsteɪnəbəl peɪs"},
{"id":935,"en":"Scope Cut","say":"Scope Cut","also":[],"gloss":"范围裁剪","explain":"为了守住日期或质量，明确从这一版拿掉一部分功能，并记下来。","band":"敏捷","ipa":"skoʊp kət","tag":"游戏"},
{"id":900,"en":"Scrum of Scrums","say":"Scrum of Scrums","also":[],"gloss":"Scrum of Scrums","explain":"几个 Scrum 团队各派代表同步依赖和障碍。","band":"敏捷","ipa":"scrum əv scrums"},
{"id":903,"en":"Product Goal","say":"Product Goal","also":[],"gloss":"产品目标","explain":"产品要达到的长期目标，产品待办为它服务。","band":"敏捷","ipa":"ˈprɑdəkt goʊl"},
{"id":904,"en":"Sprint Goal","say":"Sprint Goal","also":[],"gloss":"冲刺目标","explain":"这一个冲刺为什么而做的一句话目标，用来在范围微调时保持方向。","band":"敏捷","ipa":"sprɪnt goʊl"},
{"id":246,"en":"Predictive Life Cycle","say":"Predictive Life Cycle","also":[],"gloss":"预测型生命周期","explain":"范围早期就定下来，按计划推进，也常被叫做瀑布。","band":"敏捷","ipa":"prɪˈdɪktɪv laɪf ˈsaɪkəl"},
{"id":247,"en":"Waterfall","say":"Waterfall","also":[],"gloss":"瀑布","explain":"预测型做法的俗称：阶段依次进行，范围早期就定下来。","band":"敏捷","ipa":"ˈwɔtərˌfɔl"},
{"id":248,"en":"Iterative Life Cycle","say":"Iterative Life Cycle","also":[],"gloss":"迭代型生命周期","explain":"通过反复循环把同一个成果做得更成熟，反馈用来改进。","band":"敏捷","ipa":"ˈɪtərˌeɪtɪv laɪf ˈsaɪkəl"},
{"id":249,"en":"Incremental Life Cycle","say":"Incremental Life Cycle","also":[],"gloss":"增量型生命周期","explain":"分段交出可用的增量，客户可以更早用上一部分。","band":"敏捷","ipa":"ˌɪnkrəˈmɛntəl laɪf ˈsaɪkəl"},
{"id":936,"en":"Content Calendar","say":"Content Calendar","also":[],"gloss":"内容日历","explain":"按周或按赛季排好即将上线的活动、版本和内容，方便制作和运营对齐。","band":"敏捷","ipa":"ˈkɑntɛnt ˈkæləndər","tag":"游戏"},
{"id":250,"en":"Adaptive Life Cycle","say":"Adaptive Life Cycle","also":[],"gloss":"适应型生命周期","explain":"范围逐渐清晰，用短周期响应变化，敏捷属于这一类。","band":"敏捷","ipa":"əˈdæptɪv laɪf ˈsaɪkəl"},
{"id":251,"en":"Hybrid Life Cycle","say":"Hybrid Life Cycle","also":[],"gloss":"混合型生命周期","explain":"同一个项目里既有预测型，也有适应型，按工作特点混用。","band":"敏捷","ipa":"ˈhaɪbrɪd laɪf ˈsaɪkəl"},
{"id":252,"en":"Delivery Cadence","say":"Delivery Cadence","also":[],"gloss":"交付节奏","explain":"成果隔多久交一次，可以是一次交清、分增量，或持续交付。","band":"敏捷","ipa":"dɪˈlɪvəri ˈkeɪdəns"},
{"id":253,"en":"Value Delivery System","say":"Value Delivery System","also":[],"gloss":"价值交付系统","explain":"组织把战略变成价值的整套体系，项目只是其中一条路径。","band":"敏捷","ipa":"ˈvælju dɪˈlɪvəri ˈsɪstəm"},
{"id":254,"en":"Benefits Realization","say":"Benefits Realization","also":[],"gloss":"收益实现","explain":"项目产出真正转化成组织收益的过程，往往发生在移交之后。","band":"敏捷","ipa":"ˈbɛnəfɪts ˈriləˈzeɪʃən"},
{"id":320,"en":"Release","say":"Release","also":[],"gloss":"发布","explain":"把一组增量正式交给用户使用。","band":"流动","ipa":"riˈlis"},
{"id":321,"en":"Release Planning","say":"Release Planning","also":[],"gloss":"发布规划","explain":"规划几个迭代之后发布哪些功能。","band":"流动","ipa":"riˈlis ˈplænɪŋ"},
{"id":937,"en":"Alpha","say":"Alpha","also":[],"gloss":"Alpha","explain":"功能大体可玩、内容还未完成的阶段，重点是把各部分整合起来并找出大问题。","band":"流动","ipa":"ˈælfə","tag":"游戏"},
{"id":322,"en":"Iteration Planning","say":"Iteration Planning","also":[],"gloss":"迭代规划","explain":"一次迭代开始时，选定本轮承诺完成的工作。","band":"流动","ipa":"ˌɪtəˈreɪʃən ˈplænɪŋ"},
{"id":323,"en":"Agile Release Planning","say":"Agile Release Planning","also":[],"gloss":"敏捷发布规划","explain":"用团队速度和故事点，粗排未来几次发布能做多少。","band":"流动","ipa":"ˈæʤəl riˈlis ˈplænɪŋ"},
{"id":938,"en":"Beta","say":"Beta","also":[],"gloss":"Beta","explain":"内容接近完整的阶段，重点转到缺陷、性能、稳定性和小范围线上验证。","band":"流动","ipa":"ˈbeɪtə","tag":"游戏"},
{"id":324,"en":"Persona","say":"Persona","also":[],"gloss":"人物角色","explain":"根据真实用户抽象出来的典型人物，用来讨论需求。","band":"流动","ipa":"pərˈsoʊnə"},
{"id":325,"en":"Prototype","say":"Prototype","also":[],"gloss":"原型","explain":"先做出一个可试用的样品，用来确认需求或设计。","band":"流动","ipa":"ˈproʊtoʊˌtaɪp"},
{"id":939,"en":"Release Candidate","say":"Release Candidate","also":["rc"],"gloss":"候选发布版","explain":"团队认为可以出货的版本。之后通常只再修阻断问题。","band":"流动","ipa":"riˈlis ˈkænədɪt","tag":"游戏"},
{"id":326,"en":"Proof of Concept","say":"Proof of Concept","also":[],"gloss":"概念验证","explain":"用一个小试验证明某个想法或技术行得通。","band":"流动","ipa":"pruf əv ˈkɑnsɛpt"},
{"id":327,"en":"Information Radiator","say":"Information Radiator","also":[],"gloss":"信息发射源","explain":"贴在显眼处的看板或图，路过的人不用询问就能看到状态。","band":"流动","ipa":"ˌɪnˌfɔrˈmeɪʃən ˈreɪdiˌeɪtər"},
{"id":940,"en":"Gold Master","say":"Gold Master","also":[],"gloss":"金版","explain":"通过内部和发行验收、可以拿去提交平台的最终母版。","band":"流动","ipa":"goʊld ˈmæstər","tag":"游戏"},
{"id":328,"en":"Visual Management","say":"Visual Management","also":[],"gloss":"目视管理","explain":"用看得见的板和图展示状态，使人不用询问就知道进展。","band":"流动","ipa":"ˈvɪʒəwəl ˈmænɪʤmənt"},
{"id":329,"en":"Work in Progress (WIP)","say":"Work in Progress","also":["wip"],"gloss":"在制品","explain":"已经开始、还没做完的工作。堆积太多，流动就会变慢。","band":"流动","ipa":"wərk ɪn ˈprɑˌgrɛs"},
{"id":941,"en":"Code Freeze","say":"Code Freeze","also":[],"gloss":"代码冻结","explain":"停止功能性代码修改，只允许修会挡住出货的缺陷。","band":"流动","ipa":"koʊd friz","tag":"游戏"},
{"id":330,"en":"WIP Limit","say":"WIP Limit","also":[],"gloss":"在制品限值","explain":"规定某一列最多同时做几件，超过就先帮忙清堵。","band":"流动","ipa":"ˈdʌbəlju aɪ pi ˈlɪmət"},
{"id":340,"en":"T-shaped Skills","say":"T-shaped Skills","also":[],"gloss":"T 型技能","explain":"一个人有一门很深的专长，同时也能帮邻近的工作。","band":"流动","ipa":"ti ʃeɪpt skɪlz"},
{"id":942,"en":"Content Complete","say":"Content Complete","also":[],"gloss":"内容完成","explain":"计划内的关卡、系统和文本都已进版本，接下来主要是打磨和修缺陷。","band":"流动","ipa":"ˈkɑntɛnt kəmˈplit","tag":"游戏"},
{"id":341,"en":"Swarming","say":"Swarming","also":[],"gloss":"蜂拥模式","explain":"多人临时集中到同一件堵住的工作上，先把它做完。","band":"流动","ipa":"sˈwɔrmɪŋ"},
{"id":342,"en":"Last Responsible Moment","say":"Last Responsible Moment","also":[],"gloss":"最后责任时刻","explain":"把决定推迟到再晚就会出问题的那个时点，以便用上最新信息。","band":"流动","ipa":"læst riˈspɑnsəbəl ˈmoʊmənt"},
{"id":943,"en":"Soft Launch","say":"Soft Launch","also":[],"gloss":"软启动","explain":"先在少数地区上线，用真实玩家验证留存和稳定性，再做全球发布。","band":"流动","ipa":"sɔft lɔnʧ","tag":"游戏"},
{"id":343,"en":"MoSCoW","say":"MoSCoW","also":[],"gloss":"MoSCoW 优先级：必须有、应该有、可以有、本次不做","explain":"把需求分成必须有、应该有、可以有、这次不做，用来取舍范围。","band":"流动","ipa":"ˈmɔˌskaʊ"},
{"id":344,"en":"Kano Model","say":"Kano Model","also":[],"gloss":"卡诺模型","explain":"把需求分成基本、期望和兴奋型，用来判断什么能真正提高满意。","band":"流动","ipa":"ˈkɑnoʊ ˈmɑdəl"},
{"id":944,"en":"Day-One Patch","say":"Day One Patch","also":[],"gloss":"首日补丁","explain":"发售当天推送的更新，用来修金版锁定之后才确认的问题。","band":"流动","ipa":"deɪ wən pæʧ","tag":"游戏"},
{"id":345,"en":"Affinity Estimating","say":"Affinity Estimating","also":[],"gloss":"亲和估算","explain":"一种估算路子。先听它靠的是历史类比、公式，还是从底层往上加。","band":"流动","ipa":"əˈfɪnɪti ˈɛstəˌmeɪtɪŋ"},
{"id":346,"en":"T-shirt Sizing","say":"T-shirt Sizing","also":[],"gloss":"T 恤尺码估算","explain":"用小号、中号、大号做很粗的相对估算。","band":"流动","ipa":"ˈtiˌsərt ˈsaɪzɪŋ"},
{"id":945,"en":"Hotfix","say":"Hotfix","also":[],"gloss":"热修复","explain":"游戏已经上线后的紧急修复，通常针对崩溃、卡死或严重的数值问题。","band":"流动","ipa":"ˈhɑtˌfɪks","tag":"游戏"},
{"id":347,"en":"Fibonacci Sequence","say":"Fibonacci Sequence","also":[],"gloss":"斐波那契数列","explain":"计划扑克常用的点数序列，数字越大，估算越粗。","band":"流动","ipa":"ˌfɪbəˈnɑʧi ˈsikwəns"},
{"id":348,"en":"Continuous Integration","say":"Continuous Integration","also":[],"gloss":"持续集成","explain":"频繁把代码合到一起并自动构建、测试，及早发现冲突。","band":"流动","ipa":"kənˈtɪnjuəs ˌɪnəˈgreɪʃən"},
{"id":946,"en":"Live Ops","say":"Live Ops","also":[],"gloss":"线上运营","explain":"上线之后持续做活动、赛季、问题响应和内容更新的工作方式。","band":"流动","ipa":"lɪv ɑps","tag":"游戏"},
{"id":349,"en":"Continuous Delivery","say":"Continuous Delivery","also":[],"gloss":"持续交付","explain":"让软件随时处于可以发布的状态。","band":"流动","ipa":"kənˈtɪnjuəs dɪˈlɪvəri"},
{"id":350,"en":"DevOps","say":"DevOps","also":[],"gloss":"DevOps","explain":"把开发、测试和运维连成一条流畅的交付链路。","band":"流动","ipa":"devops"},
{"id":947,"en":"Games as a Service","say":"Games as a Service","also":["gaas"],"gloss":"游戏即服务","explain":"把游戏当成长期运营的服务来做，而不是卖出一份就结束。","band":"流动","ipa":"geɪmz ɛz ə ˈsərvɪs","tag":"游戏"},
{"id":351,"en":"Refactoring","say":"Refactoring","also":[],"gloss":"重构","explain":"不改变外部行为，把内部结构整理干净，方便以后修改。","band":"流动","ipa":"refactoring"},
{"id":352,"en":"Test-Driven Development (TDD)","say":"Test-Driven Development","also":["tdd"],"gloss":"测试驱动开发","explain":"先写失败的测试，再写刚好能通过的代码。","band":"流动","ipa":"tɛst ˈdrɪvən dɪˈvɛləpmənt"},
{"id":948,"en":"Crash Rate","say":"Crash Rate","also":[],"gloss":"崩溃率","explain":"启动或对局中发生崩溃的比例。它常被当作能不能上线的门槛。","band":"流动","ipa":"kræʃ reɪt","tag":"游戏"},
{"id":353,"en":"Pair Programming","say":"Pair Programming","also":[],"gloss":"结对编程","explain":"两个人共用一台机器写代码，一人操作，一人随时复查。","band":"流动","ipa":"pɛr ˈproʊˌgræmɪŋ"},
{"id":354,"en":"Value Stream","say":"Value Stream","also":[],"gloss":"价值流","explain":"从提出需求到用户拿到价值所经过的全部步骤。","band":"流动","ipa":"ˈvælju strim"},
{"id":949,"en":"D1 Retention","say":"D one Retention","also":[],"gloss":"次日留存","explain":"第一天来过的玩家里，第二天还回来的比例。软启动时会重点看它。","band":"流动","ipa":"di wən riˈtɛnʃən","tag":"游戏"},
{"id":355,"en":"Value Stream Mapping","say":"Value Stream Mapping","also":[],"gloss":"价值流图","explain":"把价值流画出来，标出等待和浪费发生在哪里。","band":"流动","ipa":"ˈvælju strim ˈmæpɪŋ"},
{"id":356,"en":"Waste","say":"Waste","also":[],"gloss":"浪费","explain":"客户不愿意为之付钱的活动，比如等待、返工和多余库存。","band":"流动","ipa":"weɪst"},
{"id":950,"en":"DAU","say":"D A U","also":["dau"],"gloss":"日活跃用户","explain":"一天之内进入游戏的独立用户数，用来看当天有多少人在玩。","band":"流动","ipa":"di ə ju","tag":"游戏"},
{"id":357,"en":"Cycle Time","say":"Cycle Time","also":[],"gloss":"周期时间","explain":"真正动手做到做完所花的时间。","band":"流动","ipa":"ˈsaɪkəl taɪm"},
{"id":358,"en":"Lead Time","say":"Lead Time","also":[],"gloss":"提前期","explain":"从需求进入队列到交付给用户的全部时间，含等待。","band":"流动","ipa":"lɛd taɪm"},
{"id":951,"en":"Cost per Install","say":"Cost per Install","also":[],"gloss":"单次安装成本","explain":"买量时获得一次安装平均花多少钱。它不是挣值里的成本绩效指数。","band":"流动","ipa":"kɔst pər ˌɪnˈstɔl","tag":"游戏"},
{"id":359,"en":"Throughput","say":"Throughput","also":[],"gloss":"产量","explain":"单位时间里完成的事项数量。","band":"流动","ipa":"θˈruˌpʊt"},
{"id":360,"en":"Pull System","say":"Pull System","also":[],"gloss":"拉动式系统","explain":"后一道工序有容量时才把工作拉过来，而不是往前硬推。","band":"流动","ipa":"pʊl ˈsɪstəm"},
{"id":952,"en":"LTV","say":"L T V","also":["ltv"],"gloss":"用户生命周期价值","explain":"一个玩家从进来到离开，预计一共贡献多少收入。","band":"流动","ipa":"ɛl ti vi","tag":"游戏"},
{"id":361,"en":"Cumulative Flow Diagram (CFD)","say":"Cumulative Flow Diagram","also":["cfd"],"gloss":"累积流图","explain":"用色带显示各状态里堆积了多少工作，能看出堵塞。","band":"流动","ipa":"ˈkjumjələtɪv floʊ ˈdaɪəˌgræm"},
{"id":362,"en":"Burn Rate","say":"Burn Rate","also":[],"gloss":"燃烧率","explain":"项目花钱的速度，常拿来和计划支出比较。","band":"流动","ipa":"bərn reɪt"},
{"id":363,"en":"Queue Size","say":"Queue Size","also":[],"gloss":"队列大小","explain":"还在排队、没开始做的事项有多少。","band":"流动","ipa":"kju saɪz"},
{"id":364,"en":"Batch Size","say":"Batch Size","also":[],"gloss":"批量大小","explain":"一次迭代或一次移交里打算一起做完的工作量。","band":"流动","ipa":"bæʧ saɪz"},
{"id":891,"en":"Leading Indicator","say":"Leading Indicator","also":[],"gloss":"先行指标","explain":"在结果出现之前就能看到的信号，用来提前调整。","band":"流动","ipa":"ˈlidɪŋ ˈɪndəˌkeɪtər"},
{"id":892,"en":"Lagging Indicator","say":"Lagging Indicator","also":[],"gloss":"滞后指标","explain":"事情发生之后才量到的结果，比如已经超支多少。","band":"流动","ipa":"ˈlægɪŋ ˈɪndəˌkeɪtər"},
{"id":893,"en":"Dashboard","say":"Dashboard","also":[],"gloss":"仪表盘","explain":"把少数关键指标集中显示，让人快速判断项目健不健康。","band":"流动","ipa":"ˈdæʃˌbɔrd"},
{"id":894,"en":"Little's Law","say":"Little's Law","also":[],"gloss":"利特尔法则","explain":"在制品越多、完成越慢，交付等待就越长。所以要限制在制品。","band":"流动","ipa":"ˈlɪtəlz lɔ"},
{"id":896,"en":"Escaped Defect","say":"Escaped Defect","also":[],"gloss":"逃逸缺陷","explain":"漏到客户或下一阶段才发现的缺陷。","band":"流动","ipa":"ɪˈskeɪpt ˈdifɛkt"},
{"id":897,"en":"Cost of Delay","say":"Cost of Delay","also":[],"gloss":"延迟成本","explain":"一个功能晚交付一天，组织损失多少价值。","band":"流动","ipa":"kɔst əv dɪˈleɪ"},
{"id":898,"en":"Weighted Shortest Job First (WSJF)","say":"Weighted Shortest Job First","also":["wsjf"],"gloss":"加权最短作业优先","explain":"用延迟成本除以工作规模，优先做分数高的事项。","band":"流动","ipa":"ˈweɪtɪd ˈʃɔrtɪst ʤɑb fərst"},
{"id":899,"en":"Scaled Agile Framework (SAFe)","say":"Scaled Agile Framework","also":["safe"],"gloss":"规模化敏捷框架","explain":"把敏捷扩展到多个团队和投资组合层面的一套框架。","band":"流动","ipa":"skeɪld ˈæʤəl ˈfreɪmˌwərk"},
{"id":901,"en":"Large-Scale Scrum (LeSS)","say":"Large-Scale Scrum","also":["less"],"gloss":"大规模 Scrum","explain":"用尽量少的额外角色，把 Scrum 扩展到多个团队。","band":"流动","ipa":"ˈlɑrʤˌskeɪl scrum"},
{"id":902,"en":"Minimum Business Increment (MBI)","say":"Minimum Business Increment","also":["mbi"],"gloss":"最小业务增量","explain":"能独立给业务带来价值的最小一块交付。","band":"流动","ipa":"ˈmɪnəməm ˈbɪznɪs ˈɪnkrəmənt"},
{"id":87,"en":"Project Charter","say":"Project Charter","also":[],"gloss":"项目章程","explain":"正式批准项目存在的文件，写明目标、高层需求和项目经理的权责。","band":"规划","ipa":"ˈprɑʤɛkt ˈʧɑrtər"},
{"id":88,"en":"Project Management Plan","say":"Project Management Plan","also":[],"gloss":"项目管理计划","explain":"说明项目如何执行、监控和收尾的总计划，里面包含各分计划和基准。","band":"规划","ipa":"ˈprɑʤɛkt ˈmænɪʤmənt plæn"},
{"id":89,"en":"Business Case","say":"Business Case","also":[],"gloss":"商业论证","explain":"说明为什么值得做这个项目，用收益和成本支持是否启动。","band":"规划","ipa":"ˈbɪznɪs keɪs"},
{"id":90,"en":"Benefits Management Plan","say":"Benefits Management Plan","also":[],"gloss":"效益管理计划","explain":"规定效益如何实现、何时衡量、由谁负责。","band":"规划","ipa":"ˈbɛnəfɪts ˈmænɪʤmənt plæn"},
{"id":91,"en":"Agreement","say":"Agreement","also":[],"gloss":"协议","explain":"项目章程的输入之一，包括合同、谅解备忘录和服务协议。","band":"规划","ipa":"əˈgrimənt"},
{"id":92,"en":"Business Document","say":"Business Document","also":[],"gloss":"商业文件","explain":"主要指商业论证和效益管理计划，用来说明项目值不值得做。","band":"规划","ipa":"ˈbɪznɪs ˈdɑkjəmɛnt"},
{"id":93,"en":"Scope Management Plan","say":"Scope Management Plan","also":[],"gloss":"范围管理计划","explain":"说明这一领域打算怎么管的分计划，属于项目管理计划，不是某一次的执行结果。","band":"规划","ipa":"skoʊp ˈmænɪʤmənt plæn"},
{"id":94,"en":"Requirements Management Plan","say":"Requirements Management Plan","also":[],"gloss":"需求管理计划","explain":"说明这一领域打算怎么管的分计划，属于项目管理计划，不是某一次的执行结果。","band":"规划","ipa":"rɪkˈwaɪrmənts ˈmænɪʤmənt plæn"},
{"id":95,"en":"Schedule Management Plan","say":"Schedule Management Plan","also":[],"gloss":"进度管理计划","explain":"说明这一领域打算怎么管的分计划，属于项目管理计划，不是某一次的执行结果。","band":"规划","ipa":"ˈskɛʤʊl ˈmænɪʤmənt plæn"},
{"id":96,"en":"Cost Management Plan","say":"Cost Management Plan","also":[],"gloss":"成本管理计划","explain":"说明这一领域打算怎么管的分计划，属于项目管理计划，不是某一次的执行结果。","band":"规划","ipa":"kɔst ˈmænɪʤmənt plæn"},
{"id":97,"en":"Quality Management Plan","say":"Quality Management Plan","also":[],"gloss":"质量管理计划","explain":"说明这一领域打算怎么管的分计划，属于项目管理计划，不是某一次的执行结果。","band":"规划","ipa":"kˈwɑləti ˈmænɪʤmənt plæn"},
{"id":98,"en":"Resource Management Plan","say":"Resource Management Plan","also":[],"gloss":"资源管理计划","explain":"说明这一领域打算怎么管的分计划，属于项目管理计划，不是某一次的执行结果。","band":"规划","ipa":"ˈrisɔrs ˈmænɪʤmənt plæn"},
{"id":953,"en":"Pre-production","say":"Pre-production","also":[],"gloss":"预制作","explain":"全面铺开之前的阶段，用来验证概念、做出垂直切片，并定制作计划。","band":"规划","ipa":"pri pərˈdəkʃən","tag":"游戏"},
{"id":99,"en":"Communications Management Plan","say":"Communications Management Plan","also":[],"gloss":"沟通管理计划","explain":"说明这一领域打算怎么管的分计划，属于项目管理计划，不是某一次的执行结果。","band":"规划","ipa":"kəmˌjunəˈkeɪʃənz ˈmænɪʤmənt plæn"},
{"id":100,"en":"Risk Management Plan","say":"Risk Management Plan","also":[],"gloss":"风险管理计划","explain":"说明这一领域打算怎么管的分计划，属于项目管理计划，不是某一次的执行结果。","band":"规划","ipa":"rɪsk ˈmænɪʤmənt plæn"},
{"id":101,"en":"Procurement Management Plan","say":"Procurement Management Plan","also":[],"gloss":"采购管理计划","explain":"说明这一领域打算怎么管的分计划，属于项目管理计划，不是某一次的执行结果。","band":"规划","ipa":"proʊˈkjʊrmənt ˈmænɪʤmənt plæn"},
{"id":102,"en":"Stakeholder Engagement Plan","say":"Stakeholder Engagement Plan","also":[],"gloss":"干系人参与计划","explain":"写明如何让干系人参与、用什么方式沟通、期望他们达到哪一档参与度。","band":"规划","ipa":"ˈsteɪˌkhoʊldər ɛnˈgeɪʤmənt plæn"},
{"id":103,"en":"Change Management Plan","say":"Change Management Plan","also":[],"gloss":"变更管理计划","explain":"说明这一领域打算怎么管的分计划，属于项目管理计划，不是某一次的执行结果。","band":"规划","ipa":"ʧeɪnʤ ˈmænɪʤmənt plæn"},
{"id":104,"en":"Configuration Management Plan","say":"Configuration Management Plan","also":[],"gloss":"配置管理计划","explain":"说明这一领域打算怎么管的分计划，属于项目管理计划，不是某一次的执行结果。","band":"规划","ipa":"kənˌfɪgjərˈeɪʃən ˈmænɪʤmənt plæn"},
{"id":105,"en":"Development Approach","say":"Development Approach","also":[],"gloss":"开发方法","explain":"产品怎么做出来：预测型、迭代型、增量型、适应型，或几种混用。","band":"规划","ipa":"dɪˈvɛləpmənt əˈproʊʧ"},
{"id":106,"en":"Scope Baseline","say":"Scope Baseline","also":[],"gloss":"范围基准","explain":"经批准的对照版本。没有它，偏差就无从谈起。","band":"规划","ipa":"skoʊp ˈbeɪsˌlaɪn"},
{"id":107,"en":"Schedule Baseline","say":"Schedule Baseline","also":[],"gloss":"进度基准","explain":"经批准的对照版本。没有它，偏差就无从谈起。","band":"规划","ipa":"ˈskɛʤʊl ˈbeɪsˌlaɪn"},
{"id":108,"en":"Cost Baseline","say":"Cost Baseline","also":[],"gloss":"成本基准","explain":"经批准的对照版本。没有它，偏差就无从谈起。","band":"规划","ipa":"kɔst ˈbeɪsˌlaɪn"},
{"id":109,"en":"Performance Measurement Baseline (PMB)","say":"Performance Measurement Baseline","also":["pmb"],"gloss":"绩效测量基准","explain":"范围、进度和成本基准合在一起，挣值就拿它做对照。","band":"规划","ipa":"pərˈfɔrməns ˈmɛʒərmənt ˈbeɪsˌlaɪn"},
{"id":110,"en":"Project Scope Statement","say":"Project Scope Statement","also":[],"gloss":"项目范围说明书","explain":"详细描述项目范围、可交付成果、验收标准和除外责任。","band":"规划","ipa":"ˈprɑʤɛkt skoʊp ˈsteɪtmənt"},
{"id":954,"en":"Production","say":"Production","also":[],"gloss":"正式制作","explain":"方向已经验证之后，按计划铺开关卡、系统和内容生产的阶段。","band":"规划","ipa":"pərˈdəkʃən","tag":"游戏"},
{"id":111,"en":"Product Scope","say":"Product Scope","also":[],"gloss":"产品范围","explain":"产品应具备的特性与功能。","band":"规划","ipa":"ˈprɑdəkt skoʊp"},
{"id":112,"en":"Project Scope","say":"Project Scope","also":[],"gloss":"项目范围","explain":"为交付产品所要做的工作。","band":"规划","ipa":"ˈprɑʤɛkt skoʊp"},
{"id":113,"en":"Requirements Documentation","say":"Requirements Documentation","also":[],"gloss":"需求文件","explain":"把收集到的需求写清楚，说明它如何满足业务需要。","band":"规划","ipa":"rɪkˈwaɪrmənts ˌdɑkjəmɛnˈteɪʃən"},
{"id":114,"en":"Requirements Traceability Matrix (RTM)","say":"Requirements Traceability Matrix","also":["rtm"],"gloss":"需求跟踪矩阵","explain":"把每条需求连到来源、设计和测试，防止做丢或做多。","band":"规划","ipa":"rɪkˈwaɪrmənts traceability ˈmeɪtrɪks"},
{"id":115,"en":"Work Breakdown Structure (WBS)","say":"Work Breakdown Structure","also":["wbs"],"gloss":"工作分解结构","explain":"把项目范围逐层拆开，最底层是可以估算和控制的工作包。","band":"规划","ipa":"wərk ˈbreɪkˌdaʊn ˈstrəkʧər"},
{"id":116,"en":"WBS Dictionary","say":"WBS Dictionary","also":[],"gloss":"WBS 词典","explain":"给每个 WBS 组件写清工作内容、验收标准和责任人的说明。","band":"规划","ipa":"ˈdʌbəlju bi ɛs ˈdɪkʃəˌnɛri"},
{"id":117,"en":"Work Package","say":"Work Package","also":[],"gloss":"工作包","explain":"WBS 最底层的工作，可以估算成本、工期并分配责任。","band":"规划","ipa":"wərk ˈpækɪʤ"},
{"id":118,"en":"Planning Package","say":"Planning Package","also":[],"gloss":"规划包","explain":"WBS 里暂时还拆不细的一块，以后再用滚动式规划展开。","band":"规划","ipa":"ˈplænɪŋ ˈpækɪʤ"},
{"id":119,"en":"Control Account","say":"Control Account","also":[],"gloss":"控制账户","explain":"把范围、进度和成本对在一起看的管理控制点，挣值常挂在这里。","band":"规划","ipa":"kənˈtroʊl əˈkaʊnt"},
{"id":120,"en":"Code of Accounts","say":"Code of Accounts","also":[],"gloss":"账户编码","explain":"给 WBS 每个组件编号的系统，方便汇总成本和进度。","band":"规划","ipa":"koʊd əv əˈkaʊnts"},
{"id":121,"en":"100 Percent Rule","say":"100 Percent Rule","also":[],"gloss":"100% 规则","explain":"WBS 必须覆盖全部项目范围，下一层加起来要等于上一层，不多也不少。","band":"规划","ipa":"100 pərˈsɛnt rul"},
{"id":122,"en":"Decomposition","say":"Decomposition","also":[],"gloss":"分解","explain":"把范围或工作包逐层拆开，直到可以估算和分工。","band":"规划","ipa":"ˌdikəmpəˈzɪʃən"},
{"id":955,"en":"Outsourcing","say":"Outsourcing","also":[],"gloss":"外包","explain":"把美术、动画或本地化交给外部团队，并用里程碑和样例来验收。","band":"规划","ipa":"ˌaʊtˈsɔrsɪŋ","tag":"游戏"},
{"id":123,"en":"Scope Creep","say":"Scope Creep","also":[],"gloss":"范围蔓延","explain":"未经控制就把范围越做越大。它和镀金不同，常常来自不断加需求。","band":"规划","ipa":"skoʊp krip"},
{"id":124,"en":"Gold Plating","say":"Gold Plating","also":[],"gloss":"镀金","explain":"团队自作主张加上范围以外的功能。客户没要，也不该算进成果。","band":"规划","ipa":"goʊld ˈpleɪtɪŋ"},
{"id":125,"en":"Activity List","say":"Activity List","also":[],"gloss":"活动清单","explain":"项目要做的全部活动，每条都有标识和工作说明。","band":"规划","ipa":"ækˈtɪvɪti lɪst"},
{"id":126,"en":"Activity Attributes","say":"Activity Attributes","also":[],"gloss":"活动属性","explain":"活动的补充信息，比如紧前、负责人、假设和约束。","band":"规划","ipa":"ækˈtɪvɪti əˈtrɪˌbjuts"},
{"id":127,"en":"Milestone List","say":"Milestone List","also":[],"gloss":"里程碑清单","explain":"项目的重要时点清单，并标明哪些是强制性的。","band":"规划","ipa":"ˈmaɪlˌstoʊn lɪst"},
{"id":128,"en":"Predecessor","say":"Predecessor","also":[],"gloss":"紧前活动","explain":"必须先发生、当前活动要依赖的那一项。","band":"规划","ipa":"ˈprɛdəˌsɛsər"},
{"id":129,"en":"Successor","say":"Successor","also":[],"gloss":"紧后活动","explain":"当前活动做完或开始后，接着受影响的那一项。","band":"规划","ipa":"səkˈsɛsər"},
{"id":130,"en":"Mandatory Dependency","say":"Mandatory Dependency","also":[],"gloss":"强制性依赖关系","explain":"合同、技术或外部条件规定必须遵守的依赖，也叫硬逻辑，不能随意改顺序。","band":"规划","ipa":"ˈmændəˌtɔri dɪˈpɛndənsi"},
{"id":131,"en":"Discretionary Dependency","say":"Discretionary Dependency","also":[],"gloss":"选择性依赖关系","explain":"团队根据经验选择的依赖，也叫软逻辑，必要时可以调整。","band":"规划","ipa":"dɪˈskrɛʃəˌnɛri dɪˈpɛndənsi"},
{"id":132,"en":"External Dependency","say":"External Dependency","also":[],"gloss":"外部依赖关系","explain":"项目外面的关系，比如等供应商或监管批准，团队控制不了。","band":"规划","ipa":"ɪkˈstərnəl dɪˈpɛndənsi"},
{"id":133,"en":"Internal Dependency","say":"Internal Dependency","also":[],"gloss":"内部依赖关系","explain":"项目内部活动之间的关系，团队通常可以安排。","band":"规划","ipa":"ˌɪnˈtərnəl dɪˈpɛndənsi"},
{"id":134,"en":"Finish-to-Start (FS)","say":"Finish-to-Start","also":["fs"],"gloss":"完成到开始","explain":"最常见的逻辑关系：前一项完成，后一项才能开始。","band":"规划","ipa":"ˈfɪnɪʃ tɪ stɑrt"},
{"id":956,"en":"Certification","say":"Certification","also":[],"gloss":"平台认证","explain":"主机或商店对版本做的技术合规检查。不过这一关，就不能上架。","band":"规划","ipa":"ˌsərtəfəˈkeɪʃən","tag":"游戏"},
{"id":135,"en":"Start-to-Start (SS)","say":"Start-to-Start","also":["ss"],"gloss":"开始到开始","explain":"前一项开始之后，后一项才能开始。","band":"规划","ipa":"stɑrt tɪ stɑrt"},
{"id":136,"en":"Finish-to-Finish (FF)","say":"Finish-to-Finish","also":["ff"],"gloss":"完成到完成","explain":"前一项完成之后，后一项才能完成。","band":"规划","ipa":"ˈfɪnɪʃ tɪ ˈfɪnɪʃ"},
{"id":137,"en":"Start-to-Finish (SF)","say":"Start-to-Finish","also":["sf"],"gloss":"开始到完成","explain":"前一项开始之后，后一项才能完成。这种关系最少用。","band":"规划","ipa":"stɑrt tɪ ˈfɪnɪʃ"},
{"id":138,"en":"Lead","say":"Lead","also":[],"gloss":"提前量","explain":"紧后活动可以提前开始的重叠时间。比如前一项还没完，后一项先动。","band":"规划","ipa":"lɛd"},
{"id":139,"en":"Lag","say":"Lag","also":[],"gloss":"滞后量","explain":"紧前完成后，必须再等一段时间才能开始紧后，这段等待就是滞后量。","band":"规划","ipa":"læg"},
{"id":140,"en":"Network Diagram","say":"Network Diagram","also":[],"gloss":"网络图","explain":"用图把关系、流程或原因摊开，方便团队一起看。","band":"规划","ipa":"ˈnɛtˌwərk ˈdaɪəˌgræm"},
{"id":141,"en":"Gantt Chart","say":"Gantt Chart","also":[],"gloss":"甘特图","explain":"用图形看计划或状态，比纯表格更快发现落后。","band":"规划","ipa":"gænt ʧɑrt"},
{"id":142,"en":"Bar Chart","say":"Bar Chart","also":[],"gloss":"横道图","explain":"用图形看计划或状态，比纯表格更快发现落后。","band":"规划","ipa":"bɑr ʧɑrt"},
{"id":143,"en":"Milestone Chart","say":"Milestone Chart","also":[],"gloss":"里程碑图","explain":"用图形看计划或状态，比纯表格更快发现落后。","band":"规划","ipa":"ˈmaɪlˌstoʊn ʧɑrt"},
{"id":144,"en":"Precedence Diagramming Method (PDM)","say":"Precedence Diagramming Method","also":["pdm"],"gloss":"紧前关系绘图法","explain":"用节点表示活动、用箭线表示逻辑关系的画法，也叫节点法。","band":"规划","ipa":"ˈprɛsədəns diagramming ˈmɛθəd"},
{"id":145,"en":"Activity-on-Node (AON)","say":"Activity-on-Node","also":["aon"],"gloss":"节点法","explain":"活动写在节点上，箭线只表示依赖。现在的网络图大多是这种。","band":"规划","ipa":"ækˈtɪvɪti ɔn noʊd"},
{"id":146,"en":"Critical Path","say":"Critical Path","also":[],"gloss":"关键路径","explain":"网络图里工期最长的那条路径，它决定项目最短完工时间。","band":"规划","ipa":"ˈkrɪtɪkəl pæθ"},
{"id":957,"en":"Submission","say":"Submission","also":[],"gloss":"提审","explain":"把候选版本正式交给平台审核，同时附上已知问题和说明。","band":"规划","ipa":"səbˈmɪʃən","tag":"游戏"},
{"id":147,"en":"Critical Path Method (CPM)","say":"Critical Path Method","also":["cpm"],"gloss":"关键路径法","explain":"顺着网络计算最早和最晚时间，找出没有浮动时间的关键路径。","band":"规划","ipa":"ˈkrɪtɪkəl pæθ ˈmɛθəd"},
{"id":148,"en":"Total Float","say":"Total Float","also":[],"gloss":"总浮动时间","explain":"一项活动可以耽误多久，还不至于推迟整个项目完工。","band":"规划","ipa":"ˈtoʊtəl floʊt"},
{"id":149,"en":"Free Float","say":"Free Float","also":[],"gloss":"自由浮动时间","explain":"一项活动可以耽误多久，还不至于推迟紧后活动的最早开始。","band":"规划","ipa":"fri floʊt"},
{"id":150,"en":"Early Start (ES)","say":"Early Start","also":["es"],"gloss":"最早开始时间","explain":"一项活动在逻辑和日历允许下，最早可以开始的时间。","band":"规划","ipa":"ˈərli stɑrt"},
{"id":151,"en":"Early Finish (EF)","say":"Early Finish","also":["ef"],"gloss":"最早完成时间","explain":"从最早开始加上工期，得到的最早完成时间。","band":"规划","ipa":"ˈərli ˈfɪnɪʃ"},
{"id":152,"en":"Late Start (LS)","say":"Late Start","also":["ls"],"gloss":"最晚开始时间","explain":"不耽误项目完工的前提下，最晚必须开始的时间。","band":"规划","ipa":"leɪt stɑrt"},
{"id":153,"en":"Late Finish (LF)","say":"Late Finish","also":["lf"],"gloss":"最晚完成时间","explain":"不耽误项目完工的前提下，最晚必须完成的时间。","band":"规划","ipa":"leɪt ˈfɪnɪʃ"},
{"id":154,"en":"Forward Pass","say":"Forward Pass","also":[],"gloss":"正推法","explain":"从项目开始往后算，得出各项活动的最早开始和最早完成。","band":"规划","ipa":"ˈfɔrwərd pæs"},
{"id":155,"en":"Backward Pass","say":"Backward Pass","also":[],"gloss":"逆推法","explain":"从项目结束往前算，得出最晚完成和最晚开始。","band":"规划","ipa":"ˈbækwərd pæs"},
{"id":156,"en":"Schedule Compression","say":"Schedule Compression","also":[],"gloss":"进度压缩","explain":"不缩小范围，把进度缩短。常用的是快速跟进和赶工。","band":"规划","ipa":"ˈskɛʤʊl kəmˈprɛʃən"},
{"id":157,"en":"Fast Tracking","say":"Fast Tracking","also":[],"gloss":"快速跟进","explain":"把本来先后做的活动改成并行，进度能压短，返工风险会上升。","band":"规划","ipa":"fæst ˈtrækɪŋ"},
{"id":158,"en":"Crashing","say":"Crashing","also":[],"gloss":"赶工","explain":"加资源来缩短关键路径上的工期，进度换成本。","band":"规划","ipa":"ˈkræʃɪŋ"},
{"id":958,"en":"Localization","say":"Localization","also":[],"gloss":"本地化","explain":"把文本、语音和文化细节做成目标市场能用的版本，不只是逐字翻译。","band":"规划","ipa":"ˌloʊkələˈzeɪʃən","tag":"游戏"},
{"id":159,"en":"Resource Leveling","say":"Resource Leveling","also":[],"gloss":"资源平衡","explain":"为了解决资源超负荷而调整进度，关键路径可能因此改变。","band":"规划","ipa":"ˈrisɔrs ˈlɛvəlɪŋ"},
{"id":160,"en":"Resource Smoothing","say":"Resource Smoothing","also":[],"gloss":"资源平滑","explain":"只在浮动时间里调整资源，不改变关键路径。","band":"规划","ipa":"ˈrisɔrs sˈmuðɪŋ"},
{"id":161,"en":"Resource Optimization","say":"Resource Optimization","also":[],"gloss":"资源优化","explain":"按资源限制调整进度，包括会改变关键路径的平衡，和只用不超出浮动时间的平滑。","band":"规划","ipa":"ˈrisɔrs ɑptɪmɪˈzeɪʃən"},
{"id":162,"en":"What-if Scenario Analysis","say":"What-if Scenario Analysis","also":[],"gloss":"假设情景分析","explain":"一种分析技术，用来比较方案、追查原因或预测结果。","band":"规划","ipa":"wət ɪf sɪˈnɛrioʊ æˈnælɪsɪs"},
{"id":163,"en":"Rolling Wave Planning","say":"Rolling Wave Planning","also":[],"gloss":"滚动式规划","explain":"近期工作拆细，远期工作先粗放着，走到近处再细化。","band":"规划","ipa":"ˈroʊlɪŋ weɪv ˈplænɪŋ"},
{"id":164,"en":"Progressive Elaboration","say":"Progressive Elaboration","also":[],"gloss":"渐进明细","explain":"随着信息变多，计划和估算逐步变具体，但不是偷偷扩大范围。","band":"规划","ipa":"prəˈgrɛsɪv ɪˌlæbərˈeɪʃən"},
{"id":165,"en":"Analogous Estimating","say":"Analogous Estimating","also":[],"gloss":"类比估算","explain":"拿类似项目的历史数据来估，快，但比较粗。","band":"规划","ipa":"əˈnæləgəs ˈɛstəˌmeɪtɪŋ"},
{"id":166,"en":"Parametric Estimating","say":"Parametric Estimating","also":[],"gloss":"参数估算","explain":"用历史参数和公式计算，比如每平方米造价乘面积。","band":"规划","ipa":"ˌpɛrəˈmɛtrɪk ˈɛstəˌmeɪtɪŋ"},
{"id":167,"en":"Bottom-up Estimating","say":"Bottom-up Estimating","also":[],"gloss":"自下而上估算","explain":"从工作包逐项估算再往上加，最细，也最花时间。","band":"规划","ipa":"ˈbɑtəˌməp ˈɛstəˌmeɪtɪŋ"},
{"id":168,"en":"Three-Point Estimating","say":"Three-Point Estimating","also":[],"gloss":"三点估算","explain":"用最乐观、最可能、最悲观三个数来估，表达不确定性。","band":"规划","ipa":"θri pɔɪnt ˈɛstəˌmeɪtɪŋ"},
{"id":169,"en":"One-Point Estimating","say":"One-Point Estimating","also":[],"gloss":"单点估算","explain":"一种估算路子。先听它靠的是历史类比、公式，还是从底层往上加。","band":"规划","ipa":"wən pɔɪnt ˈɛstəˌmeɪtɪŋ"},
{"id":170,"en":"Optimistic Estimate","say":"Optimistic Estimate","also":[],"gloss":"最乐观估算","explain":"一个估算结果或估算类型。数字会随信息变多而收窄。","band":"规划","ipa":"ˌɑptɪˈmɪstɪk ˈɛstəˌmeɪt"},
{"id":959,"en":"String Freeze","say":"String Freeze","also":[],"gloss":"文本冻结","explain":"停止再改玩家能看到的文案，好让翻译和录音按稳定文本进行。","band":"规划","ipa":"strɪŋ friz","tag":"游戏"},
{"id":171,"en":"Most Likely Estimate","say":"Most Likely Estimate","also":[],"gloss":"最可能估算","explain":"一个估算结果或估算类型。数字会随信息变多而收窄。","band":"规划","ipa":"moʊst ˈlaɪkli ˈɛstəˌmeɪt"},
{"id":172,"en":"Pessimistic Estimate","say":"Pessimistic Estimate","also":[],"gloss":"最悲观估算","explain":"一个估算结果或估算类型。数字会随信息变多而收窄。","band":"规划","ipa":"ˌpɛsəˈmɪstɪk ˈɛstəˌmeɪt"},
{"id":173,"en":"Triangular Distribution","say":"Triangular Distribution","also":[],"gloss":"三角分布","explain":"三点估算的一种平均：（乐观＋最可能＋悲观）除以 3。","band":"规划","ipa":"traɪˈæŋgjələr ˌdɪstrəˈbjuʃən"},
{"id":174,"en":"Beta Distribution","say":"Beta Distribution","also":[],"gloss":"贝塔分布","explain":"PERT 用的加权平均：（乐观＋4 倍最可能＋悲观）除以 6。","band":"规划","ipa":"ˈbeɪtə ˌdɪstrəˈbjuʃən"},
{"id":175,"en":"Program Evaluation and Review Technique (PERT)","say":"Program Evaluation and Review Technique","also":["pert"],"gloss":"计划评审技术","explain":"用三点估算和加权平均来表达工期的不确定性。","band":"规划","ipa":"ˈproʊˌgræm ɪˌvæljuˈeɪʃən ənd ˌrivˈju tɛkˈnik"},
{"id":176,"en":"Standard Deviation","say":"Standard Deviation","also":[],"gloss":"标准差","explain":"在三点估算里，大约是（悲观－乐观）除以 6，用来看工期分散程度。","band":"规划","ipa":"ˈstændərd ˌdiviˈeɪʃən"},
{"id":177,"en":"Reserve","say":"Reserve","also":[],"gloss":"储备","explain":"预先留出的时间或资金，用来对付不确定性。","band":"规划","ipa":"rɪˈzərv"},
{"id":178,"en":"Contingency Reserve","say":"Contingency Reserve","also":[],"gloss":"应急储备","explain":"为已经识别的风险留的时间或钱，含在基准里，项目经理通常能动用。","band":"规划","ipa":"kənˈtɪnʤənsi rɪˈzərv"},
{"id":179,"en":"Management Reserve","say":"Management Reserve","also":[],"gloss":"管理储备","explain":"为还没识别出来的未知留的预算，不含在基准里，动用要经过批准。","band":"规划","ipa":"ˈmænɪʤmənt rɪˈzərv"},
{"id":180,"en":"Basis of Estimates","say":"Basis of Estimates","also":[],"gloss":"估算依据","explain":"说明数字是怎么来的：依据、假设、区间和置信度。","band":"规划","ipa":"ˈbeɪsɪs əv ˈɛstəˌmeɪts"}
]);
